#!/bin/bash
# Build CRIU inside the assembled mixumOS target rootfs.
#
# CRIU's parasite is generated by compel at build time and is sensitive to the
# build host's glibc. Building in the rolling Arch builder produces a binary
# that crashes on the older mixumOS target. This script runs after pacstrap,
# inside the target itself, and leaves only the runtime libraries.
set -euo pipefail

TARGET="${1:?usage: build-criu-target.sh <target-rootfs> [arch]}"
ARCH="${2:-aarch64}"
VERSION=4.1
SRC_TAR=/tmp/criu-${VERSION}.tar.gz

[ -x "$TARGET/usr/bin/pacman" ] || { echo "target has no pacman: $TARGET" >&2; exit 1; }
[ -f "$SRC_TAR" ] || curl -fsSL -o "$SRC_TAR" \
  "https://github.com/checkpoint-restore/criu/archive/refs/tags/v${VERSION}.tar.gz"
cp /etc/resolv.conf "$TARGET/etc/resolv.conf"
mkdir -p "$TARGET/tmp/criu-build"
cp "$SRC_TAR" "$TARGET/tmp/criu-build/criu.tar.gz"
chroot "$TARGET" /bin/sh -c '
set -eu
pacman -Sy --noconfirm --needed \
  base-devel git python libnet protobuf-c libnl libcap util-linux-libs nftables libbpf >/dev/null
cd /tmp/criu-build
tar xf criu.tar.gz
cd criu-4.1
sed -i "/#ifdef CONFIG_HAS_NO_LIBC_RSEQ_DEFS/,/#endif \\/\\* CONFIG_HAS_NO_LIBC_RSEQ_DEFS \\*\\//d" \
  criu/include/linux/rseq.h
make -j"$(nproc)" WERROR=0 >/tmp/criu-build.log 2>&1
install -Dm755 criu/criu /usr/bin/criu
rm -rf /usr/lib/criu
'
# Leave runtime libraries and remove the compiler toolchain.
chroot "$TARGET" /bin/sh -c '
pacman -Rns --noconfirm base-devel git python >/dev/null 2>&1 || true
rm -rf /tmp/criu-build /tmp/criu-build.log
'
rm -rf "$TARGET/tmp/criu-build"
echo "criu built in target: $TARGET/usr/bin/criu"
